import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { io } from 'socket.io-client';
import './styles.css';
import './login.css';
import './listing.css';
import './profile.css';
import './manage.css';
import './swaps.css';
import './chat.css';
import './calculator.css';
import './nearby.css';
import './admin.css';
import './flow.css';

const seedListings = [
  { id: 1, title: 'Linen wrap dress', brand: 'Mango', size: 'M', condition: 'Excellent', category: 'Dresses', location: 'Bandra, Mumbai', value: 1850, image: 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=900&q=85', owner: 'Aanya' },
  { id: 2, title: 'Vintage denim jacket', brand: 'Levi\'s', size: 'L', condition: 'Good', category: 'Outerwear', location: 'Indiranagar, Bengaluru', value: 2200, image: 'https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=900&q=85', owner: 'Mira' },
  { id: 3, title: 'Pleated midi skirt', brand: 'Zara', size: 'S', condition: 'Like new', category: 'Bottoms', location: 'Koregaon Park, Pune', value: 1450, image: 'https://images.unsplash.com/photo-1583496661160-fb5886a13d27?auto=format&fit=crop&w=900&q=85', owner: 'Rhea' },
  { id: 4, title: 'Cotton poplin shirt', brand: 'Uniqlo', size: 'M', condition: 'Excellent', category: 'Tops', location: 'Hauz Khas, Delhi', value: 1100, image: 'https://images.unsplash.com/photo-1603252110481-7ba873bf42ab?auto=format&fit=crop&w=900&q=85', owner: 'Nikhil' },
  { id: 5, title: 'Textured knit cardigan', brand: 'Fabindia', size: 'M', condition: 'Good', category: 'Knitwear', location: 'Alkapuri, Vadodara', value: 1300, image: 'https://images.unsplash.com/photo-1610652492500-ded49ceeb378?auto=format&fit=crop&w=900&q=85', owner: 'Ishita' },
  { id: 6, title: 'Wide-leg linen trousers', brand: 'COS', size: 'L', condition: 'Like new', category: 'Bottoms', location: 'Banjara Hills, Hyderabad', value: 2000, image: 'https://images.unsplash.com/photo-1506629905607-d9b1d1ee4e5f?auto=format&fit=crop&w=900&q=85', owner: 'Arjun' }
];
const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:4000';
const api = async (path, options = {}) => { const token = localStorage.getItem('cloth-token'); const response = await fetch(`${API_URL}${path}`, { ...options, headers: { 'content-type': 'application/json', ...(token ? { authorization: `Bearer ${token}` } : {}), ...options.headers } }); const body = await response.json(); if (!response.ok) throw new Error(body.message || 'Request failed'); return body.data; };

function App() {
  const [loggedIn, setLoggedIn] = useState(() => Boolean(localStorage.getItem('cloth-token')));
  const [userProfile, setUserProfile] = useState(() => JSON.parse(localStorage.getItem('cloth-profile') || 'null'));
  const [page, setPage] = useState('dashboard');
  const [selected, setSelected] = useState(seedListings[0]);
  const [listings, setListings] = useState(seedListings);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('All pieces');
  const [toast, setToast] = useState('');
  const [requests, setRequests] = useState(() => JSON.parse(localStorage.getItem('cloth-requests') || '[]'));
  const [messages, setMessages] = useState([{ text: 'Hi Aanya, I love the linen dress. Would you be open to swapping for my vintage jacket?', mine: false }, { text: 'Absolutely, it sounds like a great match. The values are within 350 points.', mine: true }]);
  const [draft, setDraft] = useState('');
  const [activeSwapId, setActiveSwapId] = useState(() => localStorage.getItem('cloth-active-swap') || '');

  useEffect(() => localStorage.setItem('cloth-requests', JSON.stringify(requests)), [requests]);
  useEffect(() => { if (loggedIn) api('/api/v1/listings').then((data) => setListings(data.items)).catch(() => {}); }, [loggedIn]);
  const notify = (message) => { setToast(message); window.setTimeout(() => setToast(''), 2800); };
  const filtered = listings.filter((item) => (category === 'All pieces' || item.category === category) && `${item.title} ${item.brand} ${item.location}`.toLowerCase().includes(search.toLowerCase()));
  const go = (next) => setPage(next);
  const requestSwap = async (details = {}) => { try { const offer = await api('/api/v1/listings', { method: 'POST', body: JSON.stringify({ title: 'Vintage knit sweater', brand: 'Nicobar', size: 'M', condition: 'Excellent', category: 'Knitwear', location: 'Bandra, Mumbai', imageUrl: seedListings[4].image }) }); const swap = await api('/api/v1/swaps', { method: 'POST', body: JSON.stringify({ requestedListingId: selected.id, offeredListingId: offer.id, message: details.message || `I would love to swap my vintage knit sweater for your ${selected.title}.`, handoverMethod: details.handoverMethod || 'local_exchange', handoverLocation: details.handoverLocation }) }); setActiveSwapId(swap.id); localStorage.setItem('cloth-active-swap', swap.id); setRequests((current) => [...current, { item: selected.title, status: 'Pending', id: swap.id }]); notify('Swap request sent to ' + (selected.owner || 'the owner')); go('dashboard'); } catch (requestError) { notify(requestError.message); } };
  const createListing = async (listing) => { try { const payload = { ...listing, value: listing.value || undefined }; if (!payload.imageUrl) delete payload.imageUrl; await api('/api/v1/listings', { method: 'POST', body: JSON.stringify(payload) }); const data = await api('/api/v1/listings'); setListings(data.items); notify('Your piece is now available to the circle'); go('browse'); } catch (createError) { notify(createError.message); } };
  const sendMessage = (event) => { event.preventDefault(); if (!draft.trim()) return; setMessages([...messages, { text: draft, mine: true }]); setDraft(''); };

  if (!loggedIn) return <Login onLogin={() => setLoggedIn(true)} />;
  return <div className="app-shell">
    <header className="topbar"><button className="brand" onClick={() => go('browse')}><span className="brand-mark">cc</span><span>cloth circle</span></button><nav className="desktop-nav"><button className={page === 'browse' ? 'active' : ''} onClick={() => go('browse')}>Discover</button><button className={page === 'nearby' ? 'active' : ''} onClick={() => go('nearby')}>Nearby</button><button className={page === 'dashboard' ? 'active' : ''} onClick={() => go('dashboard')}>My circle</button><button className={page === 'calculator' ? 'active' : ''} onClick={() => go('calculator')}>Value guide</button><button className={page === 'chat' ? 'active' : ''} onClick={() => go('chat')}>Messages <b>2</b></button></nav><button className="profile-chip" onClick={() => go('profile')}><span className="avatar">{(userProfile?.name || 'CC').slice(0, 2).toUpperCase()}</span><span>My profile</span><span className="chevron">⌄</span></button></header>
    <main>
      {page === 'browse' && <Browse search={search} setSearch={setSearch} category={category} setCategory={setCategory} listings={filtered} openItem={(item) => { setSelected(item); go('detail'); }} />}
      {page === 'nearby' && <Nearby openItem={(item) => { setSelected(item); go('detail'); }} />}
      {page === 'detail' && <Detail item={selected} back={() => go('browse')} request={() => go('request')} />}
      {page === 'request' && <SwapRequestForm item={selected} back={() => go('detail')} send={requestSwap} />}
      {page === 'create' && <CreateListing back={() => go('browse')} submit={createListing} />}
      {page === 'manage' && <ManageListings create={() => go('create')} back={() => go('dashboard')} />}
      {page === 'dashboard' && <NegotiationDashboard requests={requests} browse={() => go('create')} manage={() => go('manage')} openChat={(id) => { setActiveSwapId(id || activeSwapId); go('chat'); }} />}
      {page === 'profile' && <Profile back={() => go('dashboard')} logout={() => { localStorage.removeItem('cloth-token'); localStorage.removeItem('cloth-profile'); setUserProfile(null); setLoggedIn(false); }} />}
      {page === 'calculator' && <ValueCalculator back={() => go('browse')} />}
      {page === 'chat' && <NegotiationChatFixed swapId={activeSwapId} messages={messages} draft={draft} setDraft={setDraft} back={() => go('dashboard')} />}
      {page === 'admin' && <AdminCenter />}
    </main>
    {page !== 'admin' && <button className="admin-link" onClick={() => go('admin')}>Admin workspace</button>}
    {toast && <div className="toast">{toast}</div>}
    <footer className="mobile-tabbar">
      <button className={page === 'browse' ? 'active' : ''} onClick={() => go('browse')}>
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>
        <span>Discover</span>
      </button>
      <button className={page === 'nearby' ? 'active' : ''} onClick={() => go('nearby')}>
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="3"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2"/></svg>
        <span>Nearby</span>
      </button>
      <button className={page === 'dashboard' ? 'active center' : 'center'} onClick={() => go('dashboard')}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
        <span>My circle</span>
      </button>
      <button className={page === 'calculator' ? 'active' : ''} onClick={() => go('calculator')}>
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
        <span>Value guide</span>
      </button>
      <button className={page === 'chat' ? 'active' : ''} onClick={() => go('chat')}>
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
        <span>Messages</span>
      </button>
    </footer>
  </div>;
}

function Login({ onLogin }) {
  const [registering, setRegistering] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', password: '', location: '' });
  const [errorMessage, setErrorMessage] = useState('');
  const update = (event) => setForm({ ...form, [event.target.name]: event.target.value });
  const submit = async (event) => {
    event.preventDefault();
    setErrorMessage('');
    const response = await fetch(`${API_URL}/api/v1/auth/${registering ? 'register' : 'login'}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(form) }).catch(() => null);
    if (!response) { setErrorMessage('Start the API with npm run server, then try again.'); return; }
    const body = await response.json();
    if (!response.ok) { setErrorMessage(body.message || 'Unable to continue'); return; }
    localStorage.setItem('cloth-token', body.data.token);
    // Fetch and store user profile
    try {
      const profileRes = await fetch(`${API_URL}/api/v1/auth/me`, { headers: { authorization: `Bearer ${body.data.token}` } });
      if (profileRes.ok) {
        const profileData = await profileRes.json();
        localStorage.setItem('cloth-profile', JSON.stringify(profileData.data));
        setUserProfile(profileData.data);
      }
    } catch {}
    onLogin();
  };
  return <div className="login-page"><div className="login-art"><span className="brand-mark">cc</span><p className="eyebrow">The clothing exchange</p><h1>Keep good clothes<br /><em>in good company.</em></h1><p>Swap thoughtfully, discover locally, and let your wardrobe keep moving.</p></div><form className="login-form" onSubmit={submit}><button className="login-brand" type="button"><span className="brand-mark">cc</span> cloth circle</button><p className="eyebrow">{registering ? 'Join the circle' : 'Welcome back'}</p><h2>{registering ? 'Create your account' : 'Sign in to your circle'}</h2>{registering && <><label>Your name<input name="name" value={form.name} onChange={update} required placeholder="Keira Morgan" /></label><label>City or neighbourhood<input name="location" value={form.location} onChange={update} required placeholder="Bandra, Mumbai" /></label></>}<label>Email address<input name="email" value={form.email} onChange={update} type="email" required placeholder="you@example.com" /></label><label>Password<input name="password" value={form.password} onChange={update} type="password" minLength="8" required placeholder="8 characters minimum" /></label>{errorMessage && <p className="form-error">{errorMessage}</p>}<button className="primary-action" type="submit">{registering ? 'Create account' : 'Continue'} <span>→</span></button><p className="login-note">{registering ? 'Already a member?' : 'New to the circle?'} <button type="button" onClick={() => { setRegistering(!registering); setErrorMessage(''); }}>{registering ? 'Sign in' : 'Create an account'}</button></p></form></div>;
}

function Browse({ search, setSearch, category, setCategory, listings, openItem }) { const categories = ['All pieces', 'Dresses', 'Tops', 'Bottoms', 'Outerwear', 'Knitwear']; return <>
  <section className="browse-hero"><div><p className="eyebrow">A better way to refresh your wardrobe</p><h1>Wear more.<br /><em>Waste less.</em></h1><p className="hero-copy">Find beautiful pre-loved pieces from people in your circle, and give your own wardrobe a second life.</p></div><div className="hero-note"><span>01</span><p>Every swap keeps clothing in motion and out of landfill.</p></div></section>
  <section className="discover"><div className="section-head"><div><p className="eyebrow">The community closet</p><h2>Pieces near you</h2></div><span className="listing-count">{listings.length} available now</span></div><div className="toolbar"><label className="search"><span>⌕</span><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by piece, brand, or city" /></label><div className="filters">{categories.map((item) => <button key={item} className={category === item ? 'selected' : ''} onClick={() => setCategory(item)}>{item}</button>)}</div></div><div className="listing-grid">{listings.map((item) => <ListingCard key={item.id} item={item} onClick={() => openItem(item)} />)}</div></section>
</>; }
function ListingCard({ item, onClick }) { return <article className="listing-card" onClick={onClick}><div className="image-wrap"><img src={item.image || item.imageUrl || item.imageDataUrl} alt={item.title} /><span className="value-tag">{item.value} pts</span><button className="heart" aria-label="Save listing" onClick={(e) => e.stopPropagation()}>♡</button></div><div className="listing-info"><div><h3>{item.title}</h3><p>{item.brand} · {item.size}</p></div><span className="condition">{item.condition}</span></div><p className="location">⌖ {item.location}</p></article>; }
function Nearby({ openItem }) { const [radius, setRadius] = useState('25'); const [items, setItems] = useState([]); const [location, setLocation] = useState('Mumbai'); const [message, setMessage] = useState(''); const loadNearby = (latitude, longitude) => api(`/api/v1/listings/nearby?latitude=${latitude}&longitude=${longitude}&radius=${radius}`).then(setItems).catch((error) => setMessage(error.message)); const useLocation = () => { if (!navigator.geolocation) { setMessage('Location is unavailable. Showing Mumbai nearby swaps.'); loadNearby(19.0607, 72.8362); return; } navigator.geolocation.getCurrentPosition((position) => { setLocation('your location'); loadNearby(position.coords.latitude, position.coords.longitude); }, () => { setMessage('Location permission was not granted. Showing Mumbai nearby swaps.'); loadNearby(19.0607, 72.8362); }); }; useEffect(() => { useLocation(); }, [radius]); return <section className="nearby-page"><div className="nearby-hero"><div><p className="eyebrow">Swap close to home</p><h1>Pieces near <em>{location}</em></h1><p className="muted">Discover clothing and people close enough to make the handover easy.</p></div><button className="primary-action compact" onClick={useLocation}>⌖ Refresh location</button></div><div className="nearby-controls"><label>Search radius<select value={radius} onChange={(event) => setRadius(event.target.value)}><option value="5">Within 5 km</option><option value="25">Within 25 km</option><option value="50">Within 50 km</option><option value="100">Within 100 km</option></select></label><span>{items.length} nearby opportunities</span></div>{message && <p className="form-error">{message}</p>}{items.length === 0 ? <div className="panel empty-state"><h2>No nearby pieces yet</h2><p className="muted">Try widening your radius or add a listing with a location.</p></div> : <div className="nearby-grid">{items.map((item) => <article className="nearby-card" key={item.id} onClick={() => openItem(item)}><img src={item.imageUrl || item.imageDataUrl} alt={item.title} /><div><div className="nearby-card-head"><h2>{item.title}</h2><span>{item.distanceKm} km</span></div><p>{item.brand} · {item.size} · {item.condition}</p><p className="muted">{item.owner} · {item.ownerLocation}</p><strong>{item.value} points</strong></div></article>)}</div>}</section>; }
function Detail({ item, back, request }) { return <section className="detail-page"><button className="back" onClick={back}>← Back to pieces</button><div className="detail-layout"><img className="detail-image" src={item.image || item.imageUrl || item.imageDataUrl} alt={item.title} /><div className="detail-copy"><p className="eyebrow">{item.category} · {item.condition}</p><h1>{item.title}</h1><p className="detail-brand">{item.brand} / size {item.size}</p><div className="detail-rule" /><p className="detail-description">A beautifully kept {item.title.toLowerCase()}, ready for its next story. Swapped by {item.owner || 'a community member'} in {item.location}.</p><div className="value-panel"><span>Estimated swap value</span><strong>{item.value} <small>points</small></strong><p>Based on brand, category, and condition</p></div><div className="owner"><span className="avatar large">{(item.owner || 'CC').slice(0, 2).toUpperCase()}</span><div><strong>{item.owner || 'Community member'}</strong><p>Member since 2023 · 4 successful swaps</p></div></div><button className="primary-action" onClick={request}>Request a swap <span>→</span></button></div></div></section>; }
function SwapRequestForm({ item, back, send }) { const [method, setMethod] = useState('local_exchange'); const [message, setMessage] = useState(`Hi ${item.owner || 'there'}, I’d love to swap my vintage knit sweater for your ${item.title.toLowerCase()}. Let me know what you think!`); const [location, setLocation] = useState(''); const submit = (event) => { event.preventDefault(); send({ message, handoverMethod: method, handoverLocation: location }); }; return <section className="form-page"><button className="back" onClick={back}>← Back to item</button><div className="form-intro"><p className="eyebrow">Make it yours, fairly</p><h1>Request a swap</h1><p>You’re asking {item.owner || 'another member'} about their {item.title}. Choose how you would like to exchange it.</p></div><form className="swap-form" onSubmit={submit}><div className="swap-summary"><div><span>THEIR PIECE</span><strong>{item.title}</strong><small>{item.value} points · {item.brand}</small></div><span className="swap-arrow">↔</span><div><span>YOUR OFFER</span><strong>Vintage knit sweater</strong><small>1,650 points · Nicobar</small></div></div><div className="handover-options"><label className={method === 'local_exchange' ? 'chosen' : ''}><input type="radio" name="handover" checked={method === 'local_exchange'} onChange={() => setMethod('local_exchange')} /><span>Local exchange</span><small>Meet in a public place and swap in person.</small></label><label className={method === 'shipping' ? 'chosen' : ''}><input type="radio" name="handover" checked={method === 'shipping'} onChange={() => setMethod('shipping')} /><span>Ship the items</span><small>Discuss carriers and tracking in private chat.</small></label></div>{method === 'local_exchange' && <label>Preferred area <input value={location} onChange={(event) => setLocation(event.target.value)} placeholder="A public place near Bandra" /></label>}{method === 'shipping' && <p className="privacy-note">Do not share your full address here. Exchange shipping details privately after agreement.</p>}<label>Message <textarea value={message} onChange={(event) => setMessage(event.target.value)} required /></label><button className="primary-action" type="submit">Send swap request <span>→</span></button></form></section>; }
function CreateListing({ back, submit }) { const [form, setForm] = useState({ title: '', brand: '', size: '', condition: 'Excellent', category: 'Tops', location: '', value: '' }); const [imageLoading, setImageLoading] = useState(false); const [formError, setFormError] = useState(''); const update = (event) => setForm({ ...form, [event.target.name]: event.target.value }); const file = (event) => { const selectedFile = event.target.files?.[0]; if (!selectedFile) return; setImageLoading(true); setFormError(''); const reader = new FileReader(); reader.onload = () => { setForm((current) => ({ ...current, imageDataUrl: reader.result })); setImageLoading(false); }; reader.onerror = () => { setFormError('The image could not be read. Please choose another file.'); setImageLoading(false); }; reader.readAsDataURL(selectedFile); }; const publish = (event) => { event.preventDefault(); if (imageLoading) { setFormError('Please wait for the image to finish loading.'); return; } if (!form.imageDataUrl) { setFormError('Please choose a clothing image before publishing.'); return; } setFormError(''); submit({ ...form, value: form.value ? Number(form.value) : undefined }); }; return <section className="form-page"><button className="back" onClick={back}>← Back to pieces</button><div className="form-intro"><p className="eyebrow">Give it another story</p><h1>List a piece</h1><p>Add a few honest details so the right person can find it.</p></div><form className="swap-form listing-form" onSubmit={publish}><label>Photo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={file} required /><small className="field-help">{imageLoading ? 'Reading your image...' : form.imageDataUrl ? 'Image ready to publish.' : 'Choose a PNG, JPEG, or WebP image.'}</small></label><div className="form-fields"><label>Piece name<input name="title" value={form.title} onChange={update} required placeholder="Linen overshirt" /></label><label>Brand<input name="brand" value={form.brand} onChange={update} required placeholder="COS" /></label><label>Size<input name="size" value={form.size} onChange={update} required placeholder="M" /></label><label>Category<select name="category" value={form.category} onChange={update}><option>Tops</option><option>Dresses</option><option>Bottoms</option><option>Outerwear</option><option>Knitwear</option></select></label><label>Condition<select name="condition" value={form.condition} onChange={update}><option>Like new</option><option>Excellent</option><option>Good</option><option>Fair</option></select></label><label>Location<input name="location" value={form.location} onChange={update} required placeholder="Bandra, Mumbai" /></label><label>Estimated swap value<input name="value" value={form.value} onChange={update} type="number" min="1" placeholder="Auto-calculate" /><small className="field-help">Leave blank to calculate from brand, category, and condition.</small></label></div>{formError && <p className="form-error">{formError}</p>}<button className="primary-action" type="submit" disabled={imageLoading}>{imageLoading ? 'Preparing image...' : 'Publish listing'} <span>→</span></button></form></section>; }
function ManageListings({ create, back }) { const [items, setItems] = useState([]); const [editing, setEditing] = useState(null); const [message, setMessage] = useState(''); const refresh = () => api('/api/v1/users/me/listings').then(setItems).catch((error) => setMessage(error.message)); useEffect(() => { refresh(); }, []); const remove = async (id) => { if (!window.confirm('Remove this listing from the circle?')) return; await api(`/api/v1/listings/${id}`, { method: 'DELETE' }); refresh(); }; const save = async (item) => { await api(`/api/v1/listings/${item.id}`, { method: 'PATCH', body: JSON.stringify({ title: item.title, brand: item.brand, size: item.size, condition: item.condition, category: item.category, location: item.location, value: Number(item.value) }) }); setEditing(null); refresh(); }; return <section className="manage-page"><button className="back" onClick={back}>← Back to dashboard</button><div className="manage-heading"><div><p className="eyebrow">Your wardrobe in motion</p><h1>My listings</h1><p className="muted">Edit details, check availability, or make room for something new.</p></div><button className="primary-action compact" onClick={create}>+ List a piece</button></div>{message && <p className="form-error">{message}</p>}<div className="managed-listings">{items.length === 0 && <div className="panel empty-state"><p className="muted">You have not listed a piece yet.</p><button className="primary-action compact" onClick={create}>Create your first listing →</button></div>}{items.map((item) => editing?.id === item.id ? <ListingEditor key={item.id} item={editing} setItem={setEditing} save={save} cancel={() => setEditing(null)} /> : <article className="managed-card" key={item.id}><img src={item.imageUrl || item.imageDataUrl} alt={item.title} /><div className="managed-copy"><div className="managed-title"><h2>{item.title}</h2><span className={`availability ${item.status}`}>{item.status}</span></div><p>{item.brand} · Size {item.size} · {item.condition}</p><p className="muted">{item.category} · {item.location}</p><strong>{item.value} points</strong></div><div className="managed-actions"><button onClick={() => setEditing({ ...item })}>Edit</button><button onClick={() => remove(item.id)}>Remove</button></div></article>)}</div></section>; }
function ListingEditor({ item, setItem, save, cancel }) { const update = (event) => setItem({ ...item, [event.target.name]: event.target.value }); return <form className="managed-card editor-card" onSubmit={(event) => { event.preventDefault(); save(item); }}><img src={item.imageUrl || item.imageDataUrl} alt={item.title} /><div className="editor-fields"><input name="title" value={item.title} onChange={update} required /><input name="brand" value={item.brand} onChange={update} required /><input name="size" value={item.size} onChange={update} required /><select name="condition" value={item.condition} onChange={update}><option>Like new</option><option>Excellent</option><option>Good</option><option>Fair</option></select><input name="category" value={item.category} onChange={update} required /><input name="location" value={item.location} onChange={update} required /><input name="value" type="number" min="1" value={item.value} onChange={update} required /></div><div className="managed-actions"><button type="submit">Save</button><button type="button" onClick={cancel}>Cancel</button></div></form>; }
function ValueCalculator({ back }) { const [form, setForm] = useState({ category: 'Dresses', brand: 'Mango', condition: 'Excellent' }); const [value, setValue] = useState(null); const [matches, setMatches] = useState([]); const [compare, setCompare] = useState({ category: 'Outerwear', brand: "Levi's", condition: 'Good' }); const [compareValue, setCompareValue] = useState(null); const update = (setter) => (event) => setter((current) => ({ ...current, [event.target.name]: event.target.value })); const estimate = async (event) => { event.preventDefault(); const result = await api('/api/v1/value/estimate', { method: 'POST', body: JSON.stringify(form) }); setValue(result.value); const available = await api(`/api/v1/value/matches?value=${result.value}&category=${encodeURIComponent(form.category)}`); setMatches(available); }; const estimateCompare = async (event) => { event.preventDefault(); const result = await api('/api/v1/value/estimate', { method: 'POST', body: JSON.stringify(compare) }); setCompareValue(result.value); }; const difference = value && compareValue ? Math.abs(value - compareValue) : null; return <section className="calculator-page"><button className="back" onClick={back}>← Back to pieces</button><div className="form-intro"><p className="eyebrow">Trade with confidence</p><h1>Value guide</h1><p>Estimate a fair swap value from category, brand, and condition. These are points for comparison, never a cash price.</p></div><div className="calculator-grid"><form className="calculator-card" onSubmit={estimate}><h2>Your piece</h2><ValueFields values={form} update={update(setForm)} /><button className="primary-action" type="submit">Estimate value <span>→</span></button>{value && <div className="estimate-result"><span>ESTIMATED SWAP VALUE</span><strong>{value} <small>points</small></strong><p>Based on category, brand tier, and condition.</p></div>}</form><form className="calculator-card comparison-card" onSubmit={estimateCompare}><h2>Compare a piece</h2><ValueFields values={compare} update={update(setCompare)} /><button className="secondary-action" type="submit">Compare values</button>{compareValue && <div className="estimate-result secondary-result"><span>THEIR ESTIMATED VALUE</span><strong>{compareValue} <small>points</small></strong></div>}</form></div>{difference !== null && <div className={`fair-banner ${difference <= 250 ? 'fair' : ''}`}><strong>{difference <= 250 ? 'Fair match' : 'Value gap to discuss'}</strong><span>{difference} points difference</span><p>{difference <= 250 ? 'These pieces are close enough to begin a conversation.' : 'Use chat to negotiate the condition, extras, or exchange details.'}</p></div>}<div className="match-panel"><div className="panel-head"><h2>Suggested fair matches</h2><span className="muted">Within 500 points</span></div>{matches.length === 0 ? <p className="muted">Estimate your piece to see similar available listings.</p> : <div className="match-list">{matches.map((match) => <div className="match-row" key={match.id}><strong>{match.title}</strong><span>{match.value} points</span><b>{match.fair ? 'Fair match' : `${match.difference} gap`}</b></div>)}</div>}</div></section>; }
function ValueFields({ values, update }) { return <div className="value-fields"><label>Category<select name="category" value={values.category} onChange={update}><option>Dresses</option><option>Tops</option><option>Bottoms</option><option>Outerwear</option><option>Knitwear</option></select></label><label>Brand<input name="brand" value={values.brand} onChange={update} required /></label><label>Condition<select name="condition" value={values.condition} onChange={update}><option>Like new</option><option>Excellent</option><option>Good</option><option>Fair</option></select></label></div>; }
function Profile({ back, logout }) { const [profile, setProfile] = useState({ name: '', email: '', contactDetails: '', location: '', bio: '' }); const [message, setMessage] = useState(''); useEffect(() => { api('/api/v1/auth/me').then(setProfile).catch(() => {}); }, []); const update = (event) => setProfile({ ...profile, [event.target.name]: event.target.value }); const save = async (event) => { event.preventDefault(); try { const saved = await api('/api/v1/users/me', { method: 'PATCH', body: JSON.stringify({ name: profile.name, contactDetails: profile.contactDetails, location: profile.location, bio: profile.bio }) }); setProfile(saved); setMessage('Profile saved'); } catch (saveError) { setMessage(saveError.message); } }; return <section className="profile-page"><button className="back" onClick={back}>← Back to dashboard</button><div className="profile-heading"><span className="avatar profile-avatar">{(profile.name || 'KM').slice(0, 2).toUpperCase()}</span><div><p className="eyebrow">Your identity in the circle</p><h1>Personal profile</h1><p className="muted">Keep your details current so nearby swappers know how to find you.</p></div></div><form className="profile-form" onSubmit={save}><label>Full name<input name="name" value={profile.name} onChange={update} required /></label><label>Email address<input value={profile.email} readOnly /></label><label>Contact details<input name="contactDetails" value={profile.contactDetails || ''} onChange={update} placeholder="Optional phone or preferred contact" /><small className="field-help">Kept private until a swap is accepted.</small></label><label>Location<input name="location" value={profile.location} onChange={update} required /></label><label>Bio<textarea name="bio" value={profile.bio || ''} onChange={update} placeholder="A little about your style and what you like to swap..." /></label><div className="profile-actions"><button className="primary-action" type="submit">Save profile <span>→</span></button><button className="logout-button" type="button" onClick={logout}>Sign out</button>{message && <span className="save-message">{message}</span>}</div></form></section>; }
function NegotiationDashboard({ requests, browse, manage, openChat }) { const [history, setHistory] = useState([]); const [notice, setNotice] = useState(''); const load = () => api('/api/v1/swaps').then(setHistory).catch(() => setHistory(requests)); useEffect(() => { load(); }, [requests]); const updateStatus = async (id, status) => { try { await api(`/api/v1/swaps/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); setNotice(status === 'in_negotiation' ? 'Agreement confirmed. You can continue negotiating in chat.' : `Swap ${status}`); load(); } catch (error) { setNotice(error.message); } }; const pending = history.filter((swap) => ['pending', 'accepted', 'in_negotiation'].includes(swap.status)).length; const completed = history.filter((swap) => swap.status === 'completed').length; return <section className="dashboard"><div className="dashboard-head"><div><p className="eyebrow">Good morning, Keira</p><h1>Your circle</h1><p className="muted">A little home for your wardrobe and swaps.</p></div><button className="primary-action compact" onClick={browse}>+ List a piece</button></div><div className="stats"><div><span>MY PIECES</span><strong>12</strong><small>2 awaiting a new home</small></div><div><span>IN PROGRESS</span><strong>{pending}</strong><small>{pending ? 'Active negotiations' : 'No active requests'}</small></div><div><span>COMPLETED SWAPS</span><strong>{completed}</strong><small>Successful exchanges</small></div></div>{notice && <p className="swap-notice">{notice}</p>}<div className="swap-columns"><div className="panel"><div className="panel-head"><h2>Incoming requests</h2><span className="muted">People asking about your pieces</span></div>{history.filter((swap) => swap.direction === 'incoming').map((swap) => <NegotiationRequestRow key={swap.id} swap={swap} incoming updateStatus={updateStatus} openChat={openChat} />)}{!history.some((swap) => swap.direction === 'incoming') && <p className="muted empty-state">Incoming requests will appear here.</p>}</div><div className="panel"><div className="panel-head"><h2>Sent requests</h2><button onClick={manage}>My listings →</button></div>{history.filter((swap) => swap.direction === 'outgoing').map((swap) => <NegotiationRequestRow key={swap.id} swap={swap} updateStatus={updateStatus} openChat={openChat} />)}{!history.some((swap) => swap.direction === 'outgoing') && <p className="muted empty-state">Your sent requests will appear here.</p>}</div></div><div className="panel history-panel"><div className="panel-head"><h2>Swap history</h2><span className="muted">Every request, clearly tracked</span></div>{history.map((swap) => <div className="status-line" key={`history-${swap.id}`}><span className={`status-dot ${swap.status}`} /><div><strong>{swap.requestedListing} ↔ {swap.offeredListing}</strong><p>{swap.direction === 'incoming' ? 'Incoming' : 'Sent'} · {new Date(swap.createdAt || Date.now()).toLocaleDateString()}</p></div><button className="chat-link" onClick={() => openChat(swap.id)}>Open chat</button><span className={`status-label ${swap.status}`}>{swap.status}</span></div>)}</div></section>; }
function NegotiationRequestRow({ swap, incoming, updateStatus, openChat }) { return <div className="swap-request-row"><div><strong>{swap.requestedListing} ↔ {swap.offeredListing}</strong><p>{incoming ? 'Incoming offer' : 'Your request'} · {swap.message || 'Swap details'}</p><small>{swap.handoverMethod === 'shipping' ? 'Shipping exchange' : 'Local exchange'}{swap.handoverLocation ? ` · ${swap.handoverLocation}` : ''}</small></div><span className={`status-label ${swap.status}`}>{swap.status}</span><div className="request-actions"><button onClick={() => openChat(swap.id)}>Open chat</button>{incoming && swap.status === 'pending' && <><button onClick={() => updateStatus(swap.id, 'accepted')}>Accept</button><button onClick={() => updateStatus(swap.id, 'rejected')}>Reject</button></>}{!incoming && swap.status === 'accepted' && <button onClick={() => updateStatus(swap.id, 'in_negotiation')}>Confirm agreement</button>}{swap.status === 'in_negotiation' && <button onClick={() => updateStatus(swap.id, 'completed')}>Complete swap</button>}</div>{['accepted', 'in_negotiation'].includes(swap.status) && <FulfillmentControls swap={swap} />}</div>; }
function FulfillmentControls({ swap }) { const [status, setStatus] = useState(swap.fulfillmentStatus || 'not_started'); const [message, setMessage] = useState(''); const update = async (event) => { const next = event.target.value; setStatus(next); try { await api(`/api/v1/swaps/${swap.id}/fulfillment`, { method: 'PATCH', body: JSON.stringify({ fulfillmentStatus: next, trackingReference: swap.trackingReference, handoverLocation: swap.handoverLocation }) }); setMessage('Updated'); } catch (error) { setMessage(error.message); } }; return <div className="fulfillment-control"><label>{swap.handoverMethod === 'shipping' ? 'Shipping status' : 'Exchange status'}<select value={status} onChange={update}><option value="not_started">Not started</option><option value="arranging">Arranging details</option>{swap.handoverMethod === 'shipping' ? <option value="in_transit">In transit</option> : <option value="ready_for_exchange">Ready to exchange</option>}<option value="received">Received</option></select></label>{message && <span>{message}</span>}</div>; }
function SwapRequestRow({ swap, incoming, updateStatus }) { return <div className="swap-request-row"><div><strong>{swap.requestedListing}</strong><p>Offer: {swap.offeredListing}</p><small>{swap.message || 'Swap request'}</small></div><span className={`status-label ${swap.status}`}>{swap.status}</span>{incoming && swap.status === 'pending' && <div className="request-actions"><button onClick={() => updateStatus(swap.id, 'accepted')}>Accept</button><button onClick={() => updateStatus(swap.id, 'rejected')}>Reject</button></div>}{!incoming && swap.status === 'accepted' && <button className="complete-button" onClick={() => updateStatus(swap.id, 'completed')}>Complete</button>}</div>; }
function NegotiationChat({ swapId, messages, draft, setDraft, back }) { const [liveMessages, setLiveMessages] = useState(messages); const [swap, setSwap] = useState(null); const [notice, setNotice] = useState(''); useEffect(() => { if (!swapId) return undefined; api(`/api/v1/swaps/${swapId}/messages`).then((items) => setLiveMessages(items.map((item) => ({ text: item.content, mine: item.senderId !== swap?.ownerId })))).catch(() => {}); api('/api/v1/swaps').then((items) => setSwap(items.find((item) => item.id === swapId))).catch(() => {}); const socket = io(API_URL); socket.emit('swap:join', swapId); socket.on('swap:message', (item) => setLiveMessages((current) => [...current, { text: item.content, mine: false }])); return () => socket.disconnect(); }, [swapId]); const sendLive = async (event) => { event.preventDefault(); if (!draft.trim() || !swapId) return; const content = draft; setLiveMessages((current) => [...current, { text: content, mine: true }]); setDraft(''); const item = await api(`/api/v1/swaps/${swapId}/messages`, { method: 'POST', body: JSON.stringify({ content }) }).catch(() => null); if (item) { const socket = io(API_URL); socket.emit('swap:message', { swapId, content }); socket.disconnect(); } }; const confirm = async () => { try { await api(`/api/v1/swaps/${swapId}/status`, { method: 'PATCH', body: JSON.stringify({ status: 'in_negotiation' }) }); setSwap({ ...swap, status: 'in_negotiation' }); setNotice('Agreement confirmed. Keep discussing the handover here.'); } catch (error) { setNotice(error.message); } }; return <section className="chat-page"><button className="back" onClick={back}>← Back to dashboard</button><div className="chat-header"><div><p className="eyebrow">Private negotiation · {swap?.status || 'swap request'}</p><h1>Swap conversation</h1><p className="muted">Discuss condition, fit, handover details, and the final exchange.</p></div><span className="online"><i /> Secure chat</span></div>{notice && <p className="swap-notice">{notice}</p>}<div className="chat-toolbar"><span>Direct messages are visible only to both swap members.</span>{swap?.status === 'accepted' && <button onClick={confirm}>Confirm agreement</button>}{swap?.status === 'in_negotiation' && <span className="confirmed-badge">Agreement confirmed</span>}</div><div className="chat-window">{liveMessages.map((message, index) => <div className={`message-row ${message.mine ? 'mine' : ''}`} key={index}><span className="avatar">{message.mine ? 'KM' : 'AN'}</span><div><p>{message.text}</p><small>{message.mine ? 'You' : 'Swap member'} · {index + 1}m ago</small></div></div>)}<div className="chat-system">Agreement status · {swap?.status || 'pending'}</div></div><form className="message-form" onSubmit={sendLive}><input value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Discuss the exchange..." /><button aria-label="Send message">→</button></form></section>; }
function AdminCenter() { const [tab, setTab] = useState('overview'); const [analytics, setAnalytics] = useState({ users: 0, activeUsers: 0, engagementRate: 0, totalListings: 0, activeListings: 0, hiddenListings: 0, totalSwaps: 0, successfulSwaps: 0, swapRequestConversionRate: 0, openReports: 0 }); const [users, setUsers] = useState([]); const [items, setItems] = useState([]); const [swaps, setSwaps] = useState([]); const [reports, setReports] = useState([]); const [notice, setNotice] = useState(''); const load = () => Promise.all([api('/api/v1/admin/analytics').then(setAnalytics), api('/api/v1/admin/users').then(setUsers), api('/api/v1/admin/listings').then(setItems), api('/api/v1/admin/swaps').then(setSwaps), api('/api/v1/admin/reports').then(setReports)]).catch((error) => setNotice(error.message)); useEffect(() => { load(); }, []); const moderate = async (id, status) => { try { await api(`/api/v1/admin/listings/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); setNotice(`Listing marked ${status}`); load(); } catch (error) { setNotice(error.message); } }; const resolve = async (id, status) => { try { await api(`/api/v1/admin/reports/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); setNotice(`Report ${status}`); load(); } catch (error) { setNotice(error.message); } }; return <section className="admin-page"><p className="eyebrow">Cloth Circle / operations</p><div className="dashboard-head"><div><h1>Admin workspace</h1><p className="muted">Care for the community, keep swaps moving.</p></div><span className="admin-badge">ADMIN ACCESS</span></div><nav className="admin-tabs"><button className={tab === 'overview' ? 'active' : ''} onClick={() => setTab('overview')}>Analytics</button><button className={tab === 'users' ? 'active' : ''} onClick={() => setTab('users')}>Users ({users.length})</button><button className={tab === 'listings' ? 'active' : ''} onClick={() => setTab('listings')}>Listings ({items.length})</button><button className={tab === 'swaps' ? 'active' : ''} onClick={() => setTab('swaps')}>Swaps ({swaps.length})</button><button className={tab === 'reports' ? 'active' : ''} onClick={() => setTab('reports')}>Reports ({reports.filter((report) => report.status === 'open').length})</button></nav>{notice && <p className="admin-notice">{notice}</p>}{tab === 'overview' && <AdminAnalytics analytics={analytics} />}{tab === 'users' && <div className="panel admin-panel"><AdminPanelTitle title="Community members" detail="Accounts and roles" />{users.map((user) => <div className="admin-row" key={user.id}><span className="avatar">{user.name.slice(0, 2).toUpperCase()}</span><div><strong>{user.name}</strong><p>{user.email} · {user.location || 'Location not set'}</p></div><span className="role-badge">{user.role}</span></div>)}</div>}{tab === 'listings' && <div className="panel admin-panel"><AdminPanelTitle title="Listing moderation" detail="Review, hide, or remove inappropriate pieces" />{items.map((item) => <div className="admin-row listing-admin-row" key={item.id}><img src={item.imageUrl || item.imageDataUrl} alt="" /><div><strong>{item.title}</strong><p>{item.brand} · {item.category} · {item.location}</p></div><span className={`availability ${item.status}`}>{item.status}</span><div className="admin-actions">{item.status === 'available' && <button onClick={() => moderate(item.id, 'hidden')}>Hide</button>}{item.status !== 'removed' && <button onClick={() => moderate(item.id, 'removed')}>Remove</button>}{item.status === 'hidden' && <button onClick={() => moderate(item.id, 'available')}>Restore</button>}</div></div>)}</div>}{tab === 'swaps' && <div className="panel admin-panel"><AdminPanelTitle title="Swap activity" detail="Monitor the full exchange lifecycle" />{swaps.length === 0 && <p className="muted empty-state">No swap activity yet.</p>}{swaps.map((swap) => <div className="admin-row" key={swap.id}><span className={`status-dot ${swap.status}`} /><div><strong>{swap.requestedListingId} ↔ {swap.offeredListingId}</strong><p>{swap.requesterId} → {swap.ownerId} · {new Date(swap.createdAt).toLocaleDateString()}</p></div><span className={`status-label ${swap.status}`}>{swap.status}</span></div>)}</div>}{tab === 'reports' && <div className="panel admin-panel"><AdminPanelTitle title="Reports and disputes" detail="Investigate community concerns" />{reports.length === 0 && <p className="muted empty-state">No reports have been filed.</p>}{reports.map((report) => <div className="admin-row" key={report.id}><span className={`status-dot ${report.status}`} /><div><strong>{report.reason}</strong><p>{report.listingId || report.swapId} · Filed {new Date(report.createdAt).toLocaleDateString()}</p></div><span className={`status-label ${report.status}`}>{report.status}</span>{report.status === 'open' && <div className="admin-actions"><button onClick={() => resolve(report.id, 'investigating')}>Investigate</button><button onClick={() => resolve(report.id, 'resolved')}>Resolve</button><button onClick={() => resolve(report.id, 'dismissed')}>Dismiss</button></div>}</div>)}</div>}</section>; }
function NegotiationChatFixed({ swapId, messages, draft, setDraft, back }) {
  const [liveMessages, setLiveMessages] = useState(messages);
  const [swap, setSwap] = useState(null);
  const [notice, setNotice] = useState('');
  const socketRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    async function loadChat() {
      try {
        const swaps = await api('/api/v1/swaps');
        const activeSwap = swaps.find((item) => item.id === swapId) || swaps[0];
        if (!activeSwap) {
          setNotice('No active swap conversation is available yet. Send or accept a swap request first.');
          return;
        }
        setSwap(activeSwap);
        const storedMessages = await api(`/api/v1/swaps/${activeSwap.id}/messages`);
        if (!cancelled) setLiveMessages(storedMessages.map((item) => ({ text: item.content, mine: false })));
        const socket = io(API_URL, { transports: ['websocket', 'polling'] });
        socketRef.current = socket;
        socket.on('connect', () => socket.emit('swap:join', activeSwap.id));
        socket.on('connect_error', () => setNotice('Chat is reconnecting. Your messages are still saved.'));
        socket.on('swap:message', (item) => setLiveMessages((current) => [...current, { text: item.content, mine: false }]));
      } catch (error) {
        if (!cancelled) setNotice(error.message);
      }
    }
    loadChat();
    return () => {
      cancelled = true;
      socketRef.current?.disconnect();
      socketRef.current = null;
    };
  }, [swapId]);

  const sendMessage = async (event) => {
    event.preventDefault();
    const content = draft.trim();
    if (!content || !swap) return;
    setLiveMessages((current) => [...current, { text: content, mine: true }]);
    setDraft('');
    try {
      const saved = await api(`/api/v1/swaps/${swap.id}/messages`, { method: 'POST', body: JSON.stringify({ content }) });
      socketRef.current?.emit('swap:message', { swapId: swap.id, content, messageId: saved.id });
    } catch (error) {
      setNotice(error.message);
    }
  };

  const confirmAgreement = async () => {
    try {
      const updated = await api(`/api/v1/swaps/${swap.id}/status`, { method: 'PATCH', body: JSON.stringify({ status: 'in_negotiation' }) });
      setSwap(updated);
      setNotice('Agreement confirmed. Keep discussing the handover here.');
    } catch (error) {
      setNotice(error.message);
    }
  };

  return <section className="chat-page"><button className="back" onClick={back}>← Back to dashboard</button><div className="chat-header"><div><p className="eyebrow">Private negotiation · {swap?.status || 'swap request'}</p><h1>Swap conversation</h1><p className="muted">Discuss condition, fit, handover details, and the final exchange.</p></div><span className="online"><i /> Secure chat</span></div>{notice && <p className="swap-notice">{notice}</p>}<div className="chat-toolbar"><span>Direct messages are visible only to both swap members.</span>{swap?.status === 'accepted' && <button onClick={confirmAgreement}>Confirm agreement</button>}{swap?.status === 'in_negotiation' && <span className="confirmed-badge">Agreement confirmed</span>}</div><div className="chat-window">{liveMessages.map((message, index) => <div className={`message-row ${message.mine ? 'mine' : ''}`} key={`${index}-${message.text}`}><span className="avatar">{message.mine ? 'KM' : 'AN'}</span><div><p>{message.text}</p><small>{message.mine ? 'You' : 'Swap member'} · {index + 1}m ago</small></div></div>)}<div className="chat-system">Agreement status · {swap?.status || 'pending'}</div></div><form className="message-form" onSubmit={sendMessage}><input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={swap ? 'Discuss the exchange...' : 'Open a swap to start chatting'} disabled={!swap} /><button aria-label="Send message" disabled={!swap}>→</button></form></section>;
}

function AdminPanelTitle({ title, detail }) { return <div className="panel-head"><div><h2>{title}</h2><p className="muted">{detail}</p></div><span className="admin-date">Live data</span></div>; }
function AdminAnalytics({ analytics }) { return <><div className="stats"><div><span>CLOTHING LISTINGS</span><strong>{analytics.totalListings}</strong><small>{analytics.activeListings} currently available</small></div><div><span>SUCCESSFUL SWAPS</span><strong>{analytics.successfulSwaps}</strong><small>{analytics.totalSwaps} total requests</small></div><div><span>ACTIVE USERS</span><strong>{analytics.activeUsers}</strong><small>Active in the last 30 days</small></div></div><div className="analytics-grid"><div className="panel analytics-card"><span>USER ENGAGEMENT RATE</span><strong>{analytics.engagementRate}%</strong><p>Active users divided by all registered users.</p></div><div className="panel analytics-card"><span>SWAP REQUEST CONVERSION</span><strong>{analytics.swapRequestConversionRate}%</strong><p>Successful swaps divided by total swap requests.</p></div><div className="panel analytics-card"><span>LISTING AVAILABILITY</span><strong>{analytics.totalListings ? Math.round(analytics.activeListings / analytics.totalListings * 100) : 0}%</strong><p>Listings currently available for exchange.</p></div><div className="panel analytics-card"><span>OPEN REPORTS</span><strong>{analytics.openReports}</strong><p>Community reports requiring admin attention.</p></div></div></>; }
function Admin() { return <AdminCenter />; }

createRoot(document.getElementById('root')).render(<App />);
